  const lines = [];
  lines.push("\u2014 MAXX INTELLIGENS (objektiva system \xE4ger po\xE4ngen; analysera, ber\xE4kna ej) \u2014");
  lines.push(`${TAG.fact} Maxx Score: T${ctx.score.tier} (${ctx.score.label}), viktad percentil ${ctx.score.weightedPercentile}, svagaste l\xE4nk T${ctx.score.minTier}.`);
  const persona = personaStatement(ctx);
  if (persona) lines.push(`${TAG[persona.evidence]} ${persona.text}`);
  if (ctx.completeness) {
    lines.push(`${TAG.fact} Profilkomplett: ${ctx.completeness.pct}% (${ctx.completeness.status}), konfidens ${ctx.completeness.overallConfidence}.` + (ctx.completeness.missingCritical.length ? ` Saknas: ${ctx.completeness.missingCritical.join(", ")}.` : ""));
  }
  lines.push("TIERS:");
  for (const c of ctx.categories) {
    const bs = benchmarkStatement(ctx, c.id);
    lines.push(`  ${bs ? TAG[bs.evidence] : TAG.fact} ${c.name}: T${c.tier} (${c.tierLabel}), topp ${c.topPercent}%` + (c.usingFallback ? " [fallback]" : "") + (c.profileConfidence != null ? `, profilkonf ${c.profileConfidence}` : ""));
  }
  const bn = explainBottleneck(ctx);
